CREATE TABLE products(id INTEGER PRIMARY KEY, code TEXT UNIQUE, name TEXT NOT NULL CHECK(length(trim(name))>0), category TEXT NOT NULL, sale_unit TEXT NOT NULL CHECK(sale_unit IN ('UNIT','KG','PACK')), stock_mode TEXT NOT NULL CHECK(stock_mode IN ('EXACT','WEIGHT','MANUAL')), price_minor INTEGER NOT NULL CHECK(price_minor>=0), cost_minor INTEGER CHECK(cost_minor>=0), is_active INTEGER NOT NULL CHECK(is_active IN (0,1)), created_at TEXT NOT NULL, updated_at TEXT NOT NULL, CHECK(stock_mode='MANUAL' OR (stock_mode='WEIGHT' AND sale_unit='KG') OR (stock_mode='EXACT' AND sale_unit IN ('UNIT','PACK'))));
CREATE TABLE inventory(product_id INTEGER PRIMARY KEY REFERENCES products(id), quantity_base INTEGER CHECK(quantity_base>=0), minimum_base INTEGER CHECK(minimum_base>=0), replenishment_status TEXT NOT NULL CHECK(replenishment_status IN ('SUFICIENTE','BAJO','REPONER')), updated_at TEXT NOT NULL);
CREATE TABLE sales(id INTEGER PRIMARY KEY, created_at TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('COMPLETED','CANCELLED')), payment_method TEXT NOT NULL CHECK(payment_method IN ('CASH','TRANSFER','CARD','OTHER')), total_minor INTEGER NOT NULL CHECK(total_minor>=0), cancelled_at TEXT, cancellation_reason TEXT);
CREATE TABLE sale_items(id INTEGER PRIMARY KEY, sale_id INTEGER NOT NULL REFERENCES sales(id), product_id INTEGER NOT NULL REFERENCES products(id), product_name_snapshot TEXT NOT NULL, sale_unit_snapshot TEXT NOT NULL, quantity_base INTEGER NOT NULL CHECK(quantity_base>0), unit_price_minor INTEGER NOT NULL CHECK(unit_price_minor>=0), line_total_minor INTEGER NOT NULL CHECK(line_total_minor>=0));
CREATE TABLE stock_movements(id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES products(id), sale_id INTEGER REFERENCES sales(id), movement_type TEXT NOT NULL CHECK(movement_type IN ('SALE','RESTOCK','ADJUSTMENT','SALE_REVERSAL')), delta_base INTEGER NOT NULL, created_at TEXT NOT NULL, note TEXT);
CREATE UNIQUE INDEX reversal_once ON stock_movements(sale_id,product_id) WHERE movement_type='SALE_REVERSAL';
CREATE INDEX sales_date ON sales(created_at);
CREATE INDEX movements_product ON stock_movements(product_id,created_at);
CREATE TABLE price_changes(id INTEGER PRIMARY KEY, product_id INTEGER NOT NULL REFERENCES products(id), old_price_minor INTEGER NOT NULL, new_price_minor INTEGER NOT NULL, changed_at TEXT NOT NULL, reason TEXT);
PRAGMA user_version=1;
